1	import 'package:fpdart/fpdart.dart';
2	
3	import '../../../../core/failure/failure.dart';
4	import '../../../../core/network/api_client.dart';
5	import '../../domain/entities/entry.dart';
6	import '../models/entry_dto.dart';
7	
8	/// The entries feature's one write call so far (`entries-create`) — posts
9	/// via the shared `ApiClient`, mirroring `account_remote_data_source.dart`'s
10	/// pattern.
11	class EntriesRemoteDataSource {
12	  EntriesRemoteDataSource(this._apiClient);
13	
14	  final ApiClient _apiClient;
15	
16	  /// Sends `{content, source}` plus `mediaDurationSeconds` only when
17	  /// non-null (spec-3-2's `source: audio` entries) — this story still
18	  /// never passes `chatMessageId`/`occurredAt` (Boundaries: no `Entry`
19	  /// field beyond the modeled 9; those two are optional in the contract
20	  /// and belong to later stories/epics).
21	  Future<Either<Failure, EntryDto>> create({
22	    required String content,
23	    required EntrySource source,
24	    int? mediaDurationSeconds,
25	  }) async {
26	    final result = await _apiClient.post(
27	      'entries-create',
28	      data: {
29	        'content': content,
30	        'source': source.name,
31	        'mediaDurationSeconds': ?mediaDurationSeconds,
32	      },
33	    );
34	    return result.flatMap((json) {
35	      try {
36	        final data = json['data'] as Map<String, dynamic>;
37	        return right(EntryDto.fromJson(data));
38	      } catch (error) {
39	        // A 200 response that doesn't match the expected shape is a
40	        // client-side parse failure, never a backend-sent code — maps to
41	        // the local-only `malformedResponse` (RNF09: no exception escapes
42	        // unmapped).
43	        return left(Failure.malformedResponse(message: error.toString()));
44	      }
45	    });
46	  }
47	
48	  /// Calls `entries-list` (`ApiClient.get`) with `limit` always sent, and
49	  /// `cursor`/`source`/`dateFrom`/`dateTo` only when non-null (spec-4-1's
50	  /// own convention for an optional-in-the-contract query parameter,
51	  /// mirroring [create]'s own `mediaDurationSeconds` handling — spec-5-2
52	  /// extends it to these three new filter params). [source] is sent as
53	  /// its own `.name` (the contract's own enum string); [dateFrom]/
54	  /// [dateTo] as `.toUtc().toIso8601String()` — Review finding: a local
55	  /// (non-UTC) `DateTime.toIso8601String()` has no `Z`/offset suffix,
56	  /// which isn't valid RFC3339 and so doesn't satisfy the contract's own
57	  /// `format: date-time` (`openapi.yaml`). Converting to UTC only here,
58	  /// at the serialization boundary, keeps every caller's own local-
59	  /// calendar computation (`EntriesFilterSheet`'s "local midnight this
60	  /// Monday"/"the 1st of this month") correct — this data source never
61	  /// computes the range itself, only forwards whatever
62	  /// [EntriesRepository.list]'s own caller already resolved. Returns the
63	  /// raw page as a record — no dedicated DTO wrapper type, since
64	  /// `EntriesRepositoryImpl.list()` is this record's only reader.
65	  Future<Either<Failure, ({List<EntryDto> items, String? nextCursor})>> list({
66	    String? cursor,
67	    int limit = 20,
68	    EntrySource? source,
69	    DateTime? dateFrom,
70	    DateTime? dateTo,
71	  }) async {
72	    final result = await _apiClient.get(
73	      'entries-list',
74	      queryParameters: {
75	        'limit': limit,
76	        'cursor': ?cursor,
77	        'source': ?source?.name,
78	        'dateFrom': ?dateFrom?.toUtc().toIso8601String(),
79	        'dateTo': ?dateTo?.toUtc().toIso8601String(),
80	      },
81	    );
82	    return result.flatMap((json) {
83	      try {
84	        final data = json['data'] as List<dynamic>;
85	        final items = data
86	            .map((item) => EntryDto.fromJson(item as Map<String, dynamic>))
87	            .toList();
88	        final meta = json['meta'] as Map<String, dynamic>;
89	        final nextCursor = meta['nextCursor'] as String?;
90	        return right((items: items, nextCursor: nextCursor));
91	      } catch (error) {
92	        // Same client-side-parse-failure rationale as `create()` above.
93	        return left(Failure.malformedResponse(message: error.toString()));
94	      }
95	    });
96	  }
97	
98	  /// Calls `entries-get` (`ApiClient.get`) with [id] appended as the one
99	  /// trailing path segment (Conventions: "path parameters appended as
100	  /// trailing segments") — decodes the response's own `data` object exactly
101	  /// as [create]/[list] already do, a superset [EntryDto] already handles
102	  /// (Boundaries: "its response is a superset, same as create/list's DTO
103	  /// reuse").
104	  Future<Either<Failure, EntryDto>> get(String id) async {
105	    final result = await _apiClient.get('entries-get', pathParams: [id]);
106	    return result.flatMap((json) {
107	      try {
108	        final data = json['data'] as Map<String, dynamic>;
109	        return right(EntryDto.fromJson(data));
110	      } catch (error) {
111	        // Same client-side-parse-failure rationale as `create()`/`list()`
112	        // above.
113	        return left(Failure.malformedResponse(message: error.toString()));
114	      }
115	    });
116	  }
117	
118	  /// spec-5-1 — calls `entries-search` (`ApiClient.get`) with exactly one
119	  /// query parameter, `q` (Boundaries: no `limit`/`cursor`). The response's
120	  /// `data` array decodes with the exact same `EntryDto.fromJson` [list]
121	  /// already uses — a superset response (`similarity`/`mode` fields the
122	  /// Code Map names) is simply ignored by `json_serializable`'s generated
123	  /// `fromJson`, same convention [get]'s own superset-response doc already
124	  /// gives.
125	  Future<Either<Failure, List<EntryDto>>> search(String query) async {
126	    final result = await _apiClient.get(
127	      'entries-search',
128	      queryParameters: {'q': query},
129	    );
130	    return result.flatMap((json) {
131	      try {
132	        final data = json['data'] as List<dynamic>;
133	        final items = data
134	            .map((item) => EntryDto.fromJson(item as Map<String, dynamic>))
135	            .toList();
136	        return right(items);
137	      } catch (error) {
138	        // Same client-side-parse-failure rationale as `create()`/`list()`/
139	        // `get()` above.
140	        return left(Failure.malformedResponse(message: error.toString()));
141	      }
142	    });
143	  }
144	}
