28	/// Tela 4 — Meus Registros, spec-4-1's real build: every `Entry`,
29	/// newest-first, grouped by day, each card marked by origin. Replaces the
30	/// former `MeusRegistrosPlaceholderScreen`.
31	///
32	/// [cubit] is a DI `lazySingleton` (Code Map) — this `StatefulWidget` never
33	/// closes it (`BlocProvider.value`, same convention
34	/// `AccountSettingsScreen` already uses for its own singleton cubit); only
35	/// this screen's own [ScrollController] is this `State`'s to dispose.
36	///
37	/// The global `ExpiryOverlayHost` shows its "Sessão expirada" dialog via
38	/// `showGeneralDialog` on the `Navigator` *above* this screen's own widget
39	/// subtree (`expiry_overlay_host.dart`) — this screen is never popped or
40	/// rebuilt from scratch underneath it, so [_scrollController]'s position
41	/// and [cubit]'s state survive that overlay appearing with no extra code
42	/// needed here (Acceptance Criteria's third bullet).
43	class MeusRegistrosScreen extends StatefulWidget {
44	  const MeusRegistrosScreen({
45	    required this.cubit,
46	    required this.searchCubit,
47	    super.key,
48	  });
49	
50	  final MeusRegistrosCubit cubit;
51	
52	  /// spec-5-1 — the permanently-docked `EntriesSearchBar`'s own cubit, a DI
53	  /// `lazySingleton` like [cubit] (Code Map); this `StatefulWidget` never
54	  /// closes it either, same rationale [cubit]'s own doc above gives.
55	  final EntriesSearchCubit searchCubit;
56	
57	  @override
58	  State<MeusRegistrosScreen> createState() => _MeusRegistrosScreenState();
59	}
60	
61	class _MeusRegistrosScreenState extends State<MeusRegistrosScreen> {
62	  // RNF01: no loading UI below 300ms — same threshold/`Timer` pattern as
63	  // `BootSplashScreen`.
64	  static const _skeletonThreshold = Duration(milliseconds: 300);
65	
66	  final ScrollController _scrollController = ScrollController();
67	  Timer? _skeletonTimer;
68	  bool _showSkeleton = false;
69	
70	  /// spec-5-1 — the search surface's own 300ms skeleton threshold,
71	  /// mirroring [_skeletonTimer]/[_showSkeleton] above but keyed off
72	  /// `EntriesSearchCubit`'s `ResourceLoading` rather than
73	  /// `MeusRegistrosLoading`: started fresh on every transition into
74	  /// `ResourceLoading` (`_onSearchStateChanged` below), since unlike the
75	  /// first-load timer above (started once, in [initState]) a search can
76	  /// enter/leave loading many times across one screen visit.
77	  Timer? _searchSkeletonTimer;
78	  bool _showSearchSkeleton = false;
79	
80	  /// Review fix (round 2, spec-4-4) — guards `_openDetail` against a rapid
81	  /// double-tap on a card pushing `/meus-registros/:id` twice (stacking two
82	  /// detail-route instances); cleared once the pushed route is popped, via
83	  /// `whenComplete` below.
84	  bool _navigatingToDetail = false;
85	
86	  @override
87	  void initState() {
88	    super.initState();
89	    widget.cubit.loadFirstPage();
90	    _skeletonTimer = Timer(_skeletonThreshold, () {
91	      if (mounted) {
92	        setState(() => _showSkeleton = true);
93	      }
94	    });
95	    _scrollController.addListener(_onScroll);
96	    // Review finding: `searchCubit` is a long-lived singleton (Code Map)
97	    // that can already be `ResourceLoading` the moment this `State` is
98	    // (re)created — e.g. the user switches tabs away mid-search and back,
99	    // which tears down and rebuilds this plain `GoRoute`'s widget while the
100	    // DI-singleton cubit keeps running. `BlocConsumer`'s `listener` below
101	    // only fires on a *new* state, never for one already current at
102	    // subscription time, so without this check the search skeleton would
103	    // never arm for an in-flight search resumed this way.
104	    if (widget.searchCubit.state is ResourceLoading<List<Entry>>) {
105	      _searchSkeletonTimer = Timer(_skeletonThreshold, () {
106	        if (mounted) {
107	          setState(() => _showSearchSkeleton = true);
108	        }
109	      });
110	    }
111	  }
112	
113	  @override
114	  void dispose() {
115	    _skeletonTimer?.cancel();
116	    _searchSkeletonTimer?.cancel();
117	    _scrollController
118	      ..removeListener(_onScroll)
119	      ..dispose();
120	    super.dispose();
121	  }
122	
123	  /// `BlocConsumer<EntriesSearchCubit, ...>`'s own listener (below) — starts
124	  /// [_searchSkeletonTimer] fresh on every transition into
125	  /// `ResourceLoading`, mirroring [initState]'s one-shot [_skeletonTimer]
126	  /// but re-armed per search rather than once per screen visit; any other
127	  /// state (including a fast resolve before the 300ms threshold, RNF01)
128	  /// cancels it and resets [_showSearchSkeleton].
129	  void _onSearchStateChanged(
130	    BuildContext context,
131	    Resource<List<Entry>> state,
132	  ) {
133	    _searchSkeletonTimer?.cancel();
134	    if (state is ResourceLoading<List<Entry>>) {
135	      _searchSkeletonTimer = Timer(_skeletonThreshold, () {
136	        if (mounted) {
137	          setState(() => _showSearchSkeleton = true);
138	        }
139	      });
140	      return;
141	    }
142	    if (_showSearchSkeleton) {
143	      setState(() => _showSearchSkeleton = false);
144	    }
145	  }
146	
147	  void _openDetail(Entry entry) {
148	    if (_navigatingToDetail) {
149	      return;
150	    }
151	    _navigatingToDetail = true;
152	    context
153	        .push(
154	          '${AppRoutePaths.meusRegistros}/'
155	          '${Uri.encodeComponent(entry.id)}',
156	        )
157	        .whenComplete(() {
158	          if (mounted) {
159	            setState(() => _navigatingToDetail = false);
160	          } else {
161	            _navigatingToDetail = false;
162	          }
163	        });
164	  }
165	
166	  void _onScroll() {
167	    if (!_scrollController.hasClients) {
168	      return;
169	    }
170	    final position = _scrollController.position;
171	    // Pre-fetches a little before the exact end (reusing `spacing2xl`
172	    // purely as a scroll-distance buffer, not a new literal) for a
173	    // smoother scroll-pagination feel; `loadMore()` itself is a no-op once
174	    // there's no further page or a call is already in flight.
175	    if (position.pixels >= position.maxScrollExtent - DesignTokens.spacing2xl) {
176	      widget.cubit.loadMore();
177	    }
178	  }
179	
180	  @override
181	  Widget build(BuildContext context) {
182	    return MultiBlocProvider(
183	      providers: [
184	        BlocProvider.value(value: widget.cubit),
185	        BlocProvider.value(value: widget.searchCubit),
186	      ],
187	      child: Scaffold(
188	        backgroundColor: DesignTokens.colorSurfaceBg,
189	        body: Column(
190	          children: [
191	            const BackArrowHeader(title: 'Meus Registros'),
192	            Padding(
193	              padding: const EdgeInsets.fromLTRB(
194	                DesignTokens.spacingMd,
195	                DesignTokens.spacingMd,
196	                DesignTokens.spacingMd,
197	                0,
198	              ),
199	              // spec-5-2: `hasActiveFilters`/`onFilterTap` need the real
200	              // `MeusRegistrosCubit` — this now rebuilds on its state too,
201	              // while `EntriesSearchBar` itself stays a dumb, stateless
202	              // widget, same as before. Also rebuilds on `EntriesSearchCubit`
203	              // (code-review fix): the funnel must only read as "filled"
204	              // while the plain/filtered timeline is actually what's on
205	              // screen — filters+search integration is 5.3's job, out of
206	              // this story's scope, so "filled" next to search results
207	              // that were never filtered would be misleading.
208	              child: BlocBuilder<EntriesSearchCubit, Resource<List<Entry>>>(
209	                builder: (context, searchState) =>
210	                    BlocBuilder<MeusRegistrosCubit, MeusRegistrosState>(
211	                      builder: (context, _) => EntriesSearchBar(
212	                        onChanged: widget.searchCubit.onQueryChanged,
213	                        onFilterTap: () => EntriesFilterSheet.show(
214	                          context,
215	                          cubit: widget.cubit,
216	                        ),
217	                        hasActiveFilters:
218	                            searchState is ResourceIdle<List<Entry>> &&
219	                            widget.cubit.hasActiveFilters,
220	                      ),
221	                    ),
222	              ),
223	            ),
224	            Expanded(
225	              child: BlocConsumer<EntriesSearchCubit, Resource<List<Entry>>>(
226	                listener: _onSearchStateChanged,
227	                builder: (context, searchState) {
228	                  // Boundaries: "an empty query reverts to the normal
229	                  // timeline" — `ResourceIdle` is the only variant that
230	                  // falls through to the pre-existing
231	                  // `MeusRegistrosCubit`-driven timeline below; every other
232	                  // variant renders the search surface instead.
233	                  if (searchState is ResourceIdle<List<Entry>>) {
234	                    return BlocBuilder<MeusRegistrosCubit, MeusRegistrosState>(
235	                      builder: (context, state) {
236	                        final timeline = switch (state) {
237	                          MeusRegistrosLoading() =>
238	                            _showSkeleton
239	                                ? const _SkeletonList()
240	                                : const SizedBox.shrink(),
241	                          MeusRegistrosEmpty() => const _EmptyState(),
242	                          MeusRegistrosError(message: final message) =>
243	                            _ErrorState(
244	                              message: message,
245	                              // Code-review fix: `retryCurrentPage()`, not
246	                              // `loadFirstPage()` — the latter resets the
247	                              // active filter selection, silently turning
248	                              // a failed *filtered* retry into a
249	                              // successful unfiltered one.
250	                              onRetry: widget.cubit.retryCurrentPage,
251	                            ),
252	                          MeusRegistrosLoaded() => _EntryList(
253	                            state: state,
254	                            scrollController: _scrollController,
255	                            onRetryLoadMore: widget.cubit.retryLoadMore,
256	                            onRetryTap: (entry) => widget.cubit.retry(entry.id),
257	                            onCardTap: _openDetail,
258	                          ),
259	                        };
260	                        // spec-5-2: the active-filter chip row only ever
261	                        // renders here, inside the plain-timeline branch
262	                        // (Boundaries/Never: no combined search+filter
263	                        // query this story) — and only once a filter is
264	                        // actually active.
265	                        if (!widget.cubit.hasActiveFilters) {
266	                          return timeline;
267	                        }
268	                        return Column(
269	                          children: [
270	                            _ActiveFiltersRow(cubit: widget.cubit),
271	                            Expanded(child: timeline),
272	                          ],
273	                        );
274	                      },
275	                    );
276	                  }
277	                  return _SearchResults(
278	                    state: searchState,
279	                    showSkeleton: _showSearchSkeleton,
280	                    onCardTap: _openDetail,
281	                  );
282	                },
283	              ),
284	            ),
285	          ],
286	        ),
287	      ),
288	    );
289	  }
290	}
