77	/// A plain (non-mocktail) fake — queues one `list()` result per call, same
78	/// rationale as `meus_registros_cubit_test.dart`'s own fake, plus an
79	/// optional [firstCallGate] so a test can hold the very first `list()`
80	/// call unresolved to observe the skeleton's 300ms threshold.
81	class _FakeEntriesRepository implements EntriesRepository {
82	  final List<Either<Failure, EntriesPage>> _listResults = [];
83	  int listCallCount = 0;
84	  Completer<void>? firstCallGate;
85	
86	  /// spec-5-1 — queued `search()` results, same per-call-queue convention
87	  /// as [_listResults] above. This file's own tests never queue one
88	  /// unless they specifically exercise the new docked search bar.
89	  final List<Either<Failure, List<Entry>>> _searchResults = [];
90	  final List<String> searchCalls = [];
91	
92	  /// spec-5-1 — same [firstCallGate] rationale as `list()`'s own gate,
93	  /// applied to `search()` instead: lets a test hold the search call
94	  /// unresolved to observe `_searchSkeletonTimer`'s own 300ms threshold
95	  /// (Matrix: "Slow request"). Every queued test only ever makes one
96	  /// `search()` call, so gating unconditionally (unlike [firstCallGate]'s
97	  /// call-count check) is sufficient.
98	  Completer<void>? searchGate;
99	
100	  void queueList(Either<Failure, EntriesPage> result) {
101	    _listResults.add(result);
102	  }
103	
104	  void queueSearch(Either<Failure, List<Entry>> result) {
105	    _searchResults.add(result);
106	  }
107	
108	  @override
109	  Future<Either<Failure, Entry>> create({
110	    required String content,
111	    required EntrySource source,
112	    int? mediaDurationSeconds,
113	  }) async => throw UnimplementedError('not expected to be called');
114	
115	  /// spec-5-2 — every `source`/`dateFrom`/`dateTo` this fake's `list()`
116	  /// was called with, in order; this file's own filter tests read it to
117	  /// assert what `MeusRegistrosCubit`/the filter sheet actually sent.
118	  final List<({EntrySource? source, DateTime? dateFrom, DateTime? dateTo})>
119	  listFilterCalls = [];
120	
121	  @override
122	  Future<Either<Failure, EntriesPage>> list({
123	    String? cursor,
124	    int limit = 20,
125	    EntrySource? source,
126	    DateTime? dateFrom,
127	    DateTime? dateTo,
128	  }) async {
129	    listCallCount++;
130	    listFilterCalls.add((source: source, dateFrom: dateFrom, dateTo: dateTo));
131	    if (listCallCount == 1 && firstCallGate != null) {
132	      await firstCallGate!.future;
