18	/// Same shape as `entries_list_flow_e2e_test.dart`'s/
19	/// `entry_detail_flow_e2e_test.dart`'s own fake adapter — only the
20	/// transport boundary is faked.
21	class _FakeHttpClientAdapter implements HttpClientAdapter {
22	  final List<RequestOptions> requests = [];
23	  final List<({int statusCode, Map<String, dynamic> body})> _queue = [];
24	
25	  void queueJsonResponse(int statusCode, Map<String, dynamic> body) {
26	    _queue.add((statusCode: statusCode, body: body));
27	  }
28	
29	  void queueErrorResponse(String code, String message) {
30	    queueJsonResponse(503, {
31	      'code': code,
32	      'message': message,
33	      'retryable': true,
34	    });
35	  }
36	
37	  @override
38	  Future<ResponseBody> fetch(
39	    RequestOptions options,
40	    Stream<Uint8List>? requestStream,
41	    Future<void>? cancelFuture,
42	  ) async {
43	    requests.add(options);
44	    if (_queue.isEmpty) {
45	      throw StateError(
46	        'No queued response for ${options.method} ${options.path}',
47	      );
48	    }
49	    final next = _queue.removeAt(0);
50	    return ResponseBody.fromString(
51	      jsonEncode(next.body),
52	      next.statusCode,
53	      headers: {
54	        Headers.contentTypeHeader: [Headers.jsonContentType],
55	      },
56	    );
57	  }
58	
59	  @override
60	  void close({bool force = false}) {}
61	}
