98	    'plugins.it_nomads.com/flutter_secure_storage',
99	  );
100	  final fakeNativeStorage = <String, String>{};
101	
102	  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
103	    final args = call.arguments as Map<dynamic, dynamic>;
104	    switch (call.method) {
105	      case 'write':
106	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
107	        return null;
108	      case 'read':
109	        return fakeNativeStorage[args['key'] as String];
110	      case 'delete':
111	        fakeNativeStorage.remove(args['key'] as String);
112	        return null;
113	      case 'containsKey':
114	        return fakeNativeStorage.containsKey(args['key'] as String);
115	      default:
116	        return null;
117	    }
118	  }
119	
120	  late FakePathProviderPlatform fakePathProvider;
121	  late _FakeHttpClientAdapter adapter;
122	
123	  setUp(() async {
