143	        .setMockMethodCallHandler(secureStorageChannel, null);
144	    fakeNativeStorage.clear();
145	    await Hive.close();
146	    await resetCoreDependencies();
147	    await fakePathProvider.cleanUp();
148	  });
149	
150	  test(
151	    'happy path: search() fires a genuine GET to entries-search with the '
152	    'right URL/headers/query ({q: query}, never limit/cursor), resolves '
153	    'Right with a semantic match, and persists it to the real entries '
154	    'Hive box',
155	    () async {
156	      adapter.queueJsonResponse(200, {
157	        'data': [
158	          _entryJson(
159	            id: 'entry-1',
160	            content: 'Hoje me senti muito nervoso no trabalho.',
161	            source: 'manual',
162	            occurredAt: '2026-01-02T10:00:00Z',
163	          ),
164	        ],
165	      });
166	
167	      final result = await sl<EntriesRepository>().search('ansiedade');
168	
169	      expect(result.isRight(), isTrue);
170	      result.match((_) => fail('expected Right'), (entries) {
171	        expect(entries, hasLength(1));
172	        expect(entries.single.id, 'entry-1');
173	        expect(
174	          entries.single.content,
175	          'Hoje me senti muito nervoso no trabalho.',
176	        );
